<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Check, ChevronDown, ChevronRight, ReceiptText } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import type { TransactionRange } from '@/domain/services/date-range'
import { dayGroupTitle, groupTitleOf, groupTitleSubtitleOf, localDateKey } from '@/domain/services/date-range'
import { formatCents } from '@/domain/services/money'
import { groupTransactions, summarize } from '@/domain/services/statistics'
import { useAppStore } from '@/stores/app-store'
import CategoryIcon from '@/components/CategoryIcon.vue'
import AppDialog from '@/components/AppDialog.vue'

const store = useAppStore()
const route = useRoute()
const router = useRouter()
const allowed: TransactionRange[] = ['day', 'week', 'month', 'year']
const initial = allowed.includes(route.query.range as TransactionRange) ? route.query.range as TransactionRange : 'month'
const range = ref<TransactionRange>(initial)
const expanded = ref(new Set<string>())
const initializedRange = ref<TransactionRange>()
const activationOpen = ref(false)
const rangeMenuOpen = ref(false)
const rangeMenu = ref<HTMLElement>()
const labels: Record<TransactionRange, string> = { day: '天', week: '周', month: '月', year: '年' }

const categories = computed(() => new Map(store.categories.map((category) => [category.id, category])))
const groups = computed(() => [...groupTransactions(store.transactions, range.value)].map(([key, items]) => ({ key, items, summary: summarize(items) })))
const titleItems = computed(() => groups.value.map((group) => ({
  ...group,
  title: groupTitleOf(range.value, group.key),
  subtitle: groupTitleSubtitleOf(range.value, group.key),
})))

watch(groups, (value) => {
  if (value.length && initializedRange.value !== range.value) {
    expanded.value = new Set([value[0].key])
    initializedRange.value = range.value
  }
}, { immediate: true })
watch(range, (value) => {
  expanded.value = new Set()
  initializedRange.value = undefined
  rangeMenuOpen.value = false
  router.replace({ query: { ...route.query, range: value } })
}, { flush: 'sync' })
watch(() => route.query.range, (value) => {
  if (allowed.includes(value as TransactionRange) && value !== range.value) range.value = value as TransactionRange
})

function closeRangeMenu(event: PointerEvent): void {
  if (!rangeMenu.value?.contains(event.target as Node)) rangeMenuOpen.value = false
}

onMounted(() => {
  store.initialize()
  document.addEventListener('pointerdown', closeRangeMenu)
})
onBeforeUnmount(() => document.removeEventListener('pointerdown', closeRangeMenu))

function toggle(key: string): void {
  const next = new Set(expanded.value)
  next.has(key) ? next.delete(key) : next.add(key)
  expanded.value = next
}

function dayBuckets(items: typeof store.transactions): [string, typeof store.transactions][] {
  const buckets = new Map<string, typeof store.transactions>()
  for (const item of items) {
    const key = localDateKey(item.bookedAt)
    buckets.set(key, [...(buckets.get(key) ?? []), item])
  }
  return [...buckets]
}

function edit(id: string): void {
  if (!store.canWrite) { activationOpen.value = true; return }
  router.push(`/record/${id}`)
}
</script>

<template>
  <Teleport to="#topbar-actions">
    <div ref="rangeMenu" class="range-menu">
      <button class="range-trigger" type="button" aria-haspopup="menu" :aria-expanded="rangeMenuOpen" @click="rangeMenuOpen = !rangeMenuOpen">
        {{ labels[range] }}<ChevronDown :size="18" aria-hidden="true" />
      </button>
      <div v-if="rangeMenuOpen" class="range-options" role="menu" aria-label="流水分组方式">
        <button v-for="item in allowed" :key="item" type="button" role="menuitemradio" :aria-checked="range === item" @click="range = item">
          <Check :size="18" :class="{ hidden: range !== item }" aria-hidden="true" />
          <span :class="{ active: range === item }">{{ labels[item] }}</span>
        </button>
      </div>
    </div>
  </Teleport>

  <main class="page transactions-page">
    <section v-if="groups.length === 0" class="empty card">
      <ReceiptText :size="44" aria-hidden="true" />
      <h2>还没有流水</h2>
      <p>点击下方“记一笔”记录第一笔收支。</p>
      <RouterLink class="button primary" to="/record">记一笔</RouterLink>
    </section>

    <section v-for="group in titleItems" :key="group.key" class="transaction-group card">
      <button class="group-header" type="button" :aria-expanded="expanded.has(group.key)" @click="toggle(group.key)">
        <span class="group-title">
          <component :is="expanded.has(group.key) ? ChevronDown : ChevronRight" :size="20" />
          <span class="group-title-stack">
            <span class="group-title-primary">{{ group.title }}</span>
            <span v-if="group.subtitle" class="group-title-secondary">{{ group.subtitle }}</span>
          </span>
        </span>
        <span class="group-summary"><span class="income">收 {{ formatCents(group.summary.incomeCents) }}</span><span class="expense">支 {{ formatCents(group.summary.expenseCents) }}</span></span>
      </button>
      <div v-if="expanded.has(group.key)" class="group-content">
        <template v-for="[day, items] in dayBuckets(group.items)" :key="day">
          <div v-if="range !== 'day'" class="day-header"><span>{{ dayGroupTitle(range, day) }}</span><span>共 {{ items.length }} 笔</span></div>
          <button v-for="item in items" :key="item.id" class="transaction-row" type="button" @click="edit(item.id)">
            <span class="transaction-icon"><CategoryIcon :name="categories.get(item.categoryId)?.icon" /></span>
            <span class="transaction-main"><strong>{{ categories.get(item.categoryId)?.name ?? '未分类' }}</strong><small>{{ item.note || new Date(item.bookedAt).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }}</small></span>
            <strong class="money" :class="item.type">{{ item.type === 'income' ? '+' : '-' }}{{ formatCents(item.amountCents) }}</strong>
          </button>
        </template>
      </div>
    </section>
  </main>

  <AppDialog :open="activationOpen" title="功能未解锁" @close="activationOpen = false">
    <p>激活授权码后才能编辑流水，浏览账目不受影响。</p>
    <template #actions><button class="button primary" type="button" @click="router.push('/settings/license')">去激活</button></template>
  </AppDialog>
</template>

